importScripts('routing.js?v=110');let router;onmessage=e=>{try{const {id,type,data,start,stops,next,deferredIds}=e.data;if(type==='init'){router=new RouteCore.Router(data);postMessage({id,result:true});return;}if(!router)throw Error('Kartendaten fehlen.');const result=type==='optimize'?router.optimize(start,stops,deferredIds):type==='assemble'?router.assemble(start,stops):router.toilet(start,next);postMessage({id,result});}catch(error){postMessage({id,error:error.message});}};